import java.util.Map;

public final class Solution {
    public enum TransferMethod { GET, POST }

    public static final class TransferDirective {
        private final TransferMethod method;
        public TransferDirective(TransferMethod method) { this.method = method; }
        public TransferMethod getMethod() { return method; }
    }

    public static final class OperationOutcome {
        private final TransferDirective directive;
        private final Map<String, String> links;
        public OperationOutcome(TransferDirective directive, Map<String, String> links) {
            this.directive = directive; this.links = links;
        }
        public TransferDirective getDirective() { return directive; }
        public Map<String, String> getLinks() { return links; }
    }

    public static final class TransferRequest {
        private final TransferMethod method;
        private final String destination;
        private TransferRequest(TransferMethod method, String destination) {
            this.method = method; this.destination = destination;
        }
        public TransferMethod getMethod() { return method; }
        public String getDestination() { return destination; }
    }

    public static final class PaymentException extends Exception {
        public PaymentException(String message) { super(message); }
    }

    public static TransferRequest buildTransfer(OperationOutcome outcome) throws PaymentException {
        if (outcome == null || outcome.getDirective() == null
                || outcome.getDirective().getMethod() == null || outcome.getLinks() == null) {
            throw new PaymentException("Incomplete outcome");
        }
        String destination = outcome.getLinks().get("payment");
        if (destination == null || destination.isEmpty() || containsWhitespace(destination)) {
            throw new PaymentException("Invalid payment destination");
        }
        return new TransferRequest(outcome.getDirective().getMethod(), destination);
    }

    private static boolean containsWhitespace(String value) {
        for (int i = 0; i < value.length(); i++) {
            if (Character.isWhitespace(value.charAt(i))) return true;
        }
        return false;
    }
}
